/**
 * The deployed Worker: OpenNext's worker (`.open-next/worker.js`, generated by
 * `opennextjs-cloudflare build`) with one change to its responses.
 *
 * Pages and RSC payloads come out of the prerender cache with
 * `Cache-Control: s-maxage=31536000, stale-while-revalidate=2592000`. Safari honours
 * stale-while-revalidate in its own cache: after a deploy it showed the page it had cached,
 * whose CSS and JS files (named by content hash) no longer exist, so the page loaded with
 * neither and nothing worked until the cache was cleared (a private tab worked). Pages and
 * RSC payloads are therefore sent as `max-age=0, must-revalidate`: the browser asks every
 * time, and the page always names files that exist. Build files themselves are immutable
 * and cached for a year (public/_headers).
 */

// @ts-ignore -- generated at build time
import handler from './.open-next/worker.js'

const PAGE_CACHE_CONTROL = 'public, max-age=0, must-revalidate'

type Handler = { fetch: (request: Request, env: unknown, ctx: unknown) => Promise<Response> }

export default {
  async fetch(request: Request, env: unknown, ctx: unknown): Promise<Response> {
    const response = await (handler as Handler).fetch(request, env, ctx)
    const type = response.headers.get('content-type') ?? ''
    if (!type.startsWith('text/html') && !type.startsWith('text/x-component')) return response
    const headers = new Headers(response.headers)
    headers.set('Cache-Control', PAGE_CACHE_CONTROL)
    return new Response(response.body, { status: response.status, statusText: response.statusText, headers })
  },
}
